import { tool, type ToolResult } from "@opencode-ai/plugin/tool"
import { CAP_MESSAGE } from "./config.ts"
import type { Canceller } from "./cancel.ts"
import type { A2AEventEmitter } from "./events.ts"
import {
  ConversationStore,
  createConversationCore,
  readConfig,
  type ConfigProvider,
  type ConversationCore,
  type ConversationResult,
} from "./conversation.ts"
import type { Registry } from "./registry.ts"

export { ConversationStore, createConversationCore } from "./conversation.ts"
export type { Conversation, ConversationResult, ConfigProvider } from "./conversation.ts"

// A2A-014: the tool is now a thin wrapper over the shared conversation core.
// Callers that already own a core (the plugin) pass it in; tests may pass the
// original deps and the core is built here.
export function createAskTool(input: {
  config: ConfigProvider
  core?: ConversationCore
  store?: ConversationStore
  emit?: A2AEventEmitter
  cancel?: Canceller
  timeoutMs?: number
  pollMs?: number
  registry?: Registry
}) {
  const core =
    input.core ??
    createConversationCore({
      config: input.config,
      store: input.store ?? new ConversationStore(),
      emit: input.emit,
      cancel: input.cancel,
      timeoutMs: input.timeoutMs,
      pollMs: input.pollMs,
      registry: input.registry,
    })
  return tool({
    description:
      "Ask an allowed A2A peer agent a question and read its reply. " +
      "To follow up in the same conversation, pass the task id returned by the previous call.",
    args: {
      peer: tool.schema.string().describe("Peer name from the allowedPeers config"),
      message: tool.schema.string().describe("Text question or message to send to the peer"),
      taskId: tool.schema
        .string()
        .optional()
        .describe("Task id from a previous a2a_ask call; pass it to continue the same task"),
    },
    execute: async (args, context) => {
      const result = await core.startConversation(args.peer, args.message, {
        taskId: args.taskId,
        origin: "tool",
        sessionId: context?.sessionID,
        signal: context?.abort,
      })
      return renderResult(readConfig(input.config), args.peer, result)
    },
  })
}

function renderResult(config: { maxTurns: number }, peer: string, result: ConversationResult): ToolResult {
  if (result.terminal) return terminalResult(peer, result)
  if (result.capped) return capResult(config, peer, result)
  const lines = [`Peer: ${peer}`]
  if (result.taskId) lines.push(`Task: ${result.taskId}`)
  if (result.turn !== undefined) lines.push(`Turn: ${turnLabel(config, result.turn)}`)
  lines.push(result.reply ? `Reply: ${result.reply}` : "Reply: (none)")
  if (result.artifact) lines.push(`Artifact: ${result.artifact}`)
  return {
    title: result.turn !== undefined ? `${peer} turn ${turnLabel(config, result.turn)}` : `${peer} reply`,
    output: lines.join("\n"),
    metadata: {
      peerId: peer,
      ...(result.taskId ? { taskId: result.taskId } : {}),
      ...(result.turn !== undefined ? { turn: result.turn } : {}),
      ...(result.firstTurn !== undefined ? { firstTurn: result.firstTurn } : {}),
      state: result.state,
    },
  }
}

function turnLabel(config: { maxTurns: number }, turn: number) {
  return config.maxTurns > 0 ? `${turn}/${config.maxTurns}` : String(turn)
}

function terminalResult(peer: string, result: ConversationResult): ToolResult {
  const lines = [`Peer: ${peer}`]
  if (result.taskId) lines.push(`Task: ${result.taskId}`)
  lines.push(
    `State: ${result.state}`,
    "This task is already finished; send a new message without a taskId to start a new task.",
  )
  return {
    title: `task ${result.state}`,
    output: lines.join("\n"),
    metadata: {
      peerId: peer,
      ...(result.taskId ? { taskId: result.taskId } : {}),
      state: result.state,
    },
  }
}

function capResult(config: { maxTurns: number }, peer: string, result: ConversationResult): ToolResult {
  return {
    title: `max turns reached (${peer})`,
    output: [
      `Peer: ${peer}`,
      `Task: ${result.taskId}`,
      `Turn: ${result.turn}/${config.maxTurns}`,
      CAP_MESSAGE,
    ].join("\n"),
    metadata: {
      peerId: peer,
      taskId: result.taskId,
      turn: result.turn,
      state: "TASK_STATE_COMPLETED",
    },
  }
}

src/cancel.ts.source:
import type { ConversationStore } from "./ask.ts"
import { noopEmitter, type A2AEventEmitter } from "./events.ts"

// The cancel path the inbound bridge exposes: cancels the local task owned by
// this process, returning false when the task is unknown or already settled.
export type LocalCancel = (taskId: string) => Promise<boolean>

// A2A-012: one cancel routine for every interruption. A cancel can apply to a
// remote task (an a2a_ask conversation), a local one (an inbound task this
// process serves), or both, so every invocation attempts both sides and
// tolerates absence. Used by the tool on abort and by the bridge on a local
// run abort.
export type Canceller = (taskId: string | undefined, reason?: string) => Promise<void>

export function createCanceller(input: {
  store: ConversationStore
  emit?: A2AEventEmitter
  local?: () => LocalCancel | undefined
}): Canceller {
  const emit = input.emit ?? noopEmitter
  const done = new Set<string>()

  return async (taskId, reason) => {
    if (taskId === undefined || taskId === "" || done.has(taskId)) return
    done.add(taskId)
    const properties = {
      taskId,
      state: "TASK_STATE_CANCELED" as const,
      ...(reason === undefined ? {} : { content: reason }),
    }
    let emitted = false
    const conversation = input.store.get(taskId)
    if (conversation) {
      // Mark the conversation terminal before the request so a concurrent
      // follow-up cannot start another turn on a task we are cancelling.
      conversation.terminal = "TASK_STATE_CANCELED"
      try {
        await conversation.client.cancelTask(taskId)
      } catch {
        // Unreachable or already settled peers still end the local thread.
      }
      const emitter = conversation.emit ?? emit
      emitter("a2a.task.updated", { ...properties, peerId: conversation.peerId })
      emitted = true
    }
    const local = input.local?.()
    if (local && (await local(taskId))) emitted = true
    // The local path emits through A2AServer.onCancel; without either side
    // there is still a thread in the UI that needs its terminal state.
    if (!emitted) emit("a2a.task.updated", properties)
  }
}

src/config.ts.source:
import { z } from "zod"

// Turn cap outcome shared by the plugin and the tracker: a capped conversation
// is a bounded result, not a crash.
export const CAP_MESSAGE = "max turns reached without verdict"

export const A2AConfigSchema = z.object({
  enabled: z.boolean().default(false),
  listenPort: z.number().int().min(0).max(65535).default(0),
  allowedPeers: z.record(z.string(), z.string()).default({}),
  // 0 disables the cap: conversations stay input-required until a peer
  // completes or cancels the task.
  maxTurns: z.number().int().nonnegative().default(4),
  // This instance's self-identity, sent to peers as the x-a2a-peer header so
  // the remote host can record who is calling (A2A-007).
  name: z.string().min(1).optional(),
  // Inbound (A2A-005): agent/model for prompts arriving over A2A. Unset means
  // the opencode defaults for the project the plugin runs in.
  agent: z.string().min(1).optional(),
  model: z.string().min(1).optional(),
  // Inbound (A2A-012): a turn that runs longer than this is aborted and the
  // task fails, so a stuck provider can never leave a task WORKING forever.
  turnTimeoutMs: z.number().int().positive().default(120_000),
})
export type A2AConfig = z.infer<typeof A2AConfigSchema>

// Config can arrive from three places:
//   1. plugin options in opencode.json: ["plugin", [[spec, { a2a: {...} }]]]
//   2. OPENCODE_A2A_ENABLED=1
//   3. the plugin `config` hook, once opencode exposes an `a2a` section
// Precedence is hook > options > env > defaults; `enabled` is an OR.
export function resolveConfig(input: {
  options?: Record<string, unknown>
  env?: Record<string, string | undefined>
  hookConfig?: unknown
}): A2AConfig {
  const options = optionsSection(input.options)
  const hook = hookSection(input.hookConfig)
  const parsed = A2AConfigSchema.parse({
    ...options,
    ...hook,
    enabled: options.enabled === true || hook.enabled === true || envEnabled(input.env),
  })
  for (const [id, url] of Object.entries(parsed.allowedPeers)) requireUrl(id, url)
  if (parsed.model !== undefined) parseModel(parsed.model)
  return parsed
}

// The model config is a "provider/model" string split on the first `/`, so
// model ids that themselves contain slashes (vendor/path style) stay intact.
// Both halves must be non-empty; validated eagerly like peer URLs.
export function parseModel(model: string): { providerID: string; modelID: string } {
  const separator = model.indexOf("/")
  const modelID = model.slice(separator + 1)
  if (separator < 1 || modelID === "") throw new Error(`Invalid model for A2A: "${model}" (expected "provider/model")`)
  return { providerID: model.slice(0, separator), modelID }
}

// Plugin options may be written nested (`{ "a2a": {...} }`) or flat
// (`{ "enabled": true }`), so both shapes read naturally in opencode.json.
function optionsSection(value: unknown): Record<string, unknown> {
  if (!isRecord(value)) return {}
  if (isRecord(value.a2a)) return value.a2a
  return value
}

// The config hook receives the whole merged opencode config. Only an explicit
// `a2a` section belongs to this plugin; never treat the rest as options, or a
// future top-level key like `enabled` could switch A2A on by accident.
function hookSection(value: unknown): Record<string, unknown> {
  if (!isRecord(value)) return {}
  return isRecord(value.a2a) ? value.a2a : {}
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value)
}

function envEnabled(env: Record<string, string | undefined> | undefined) {
  const value = env?.OPENCODE_A2A_ENABLED?.toLowerCase()
  return value === "1" || value === "true"
}

export function requireUrl(id: string, url: string) {
  try {
    new URL(url)
  } catch {
    throw new Error(`Invalid URL for A2A peer "${id}": ${url}`)
  }
}

src/control.ts.source:
import path from "node:path"
import { z } from "zod"
import { ArtifactSchema, SpeakerSchema, TaskStateSchema } from "a2a"

// Local control plane contract (A2A-014). The TUI panel talks to these
// endpoints over loopback HTTP and nowhere else — the plugin never imports
// server-side modules into its TUI target. Two transports are planned:
// routes on the local opencode server, or a loopback admin endpoint hosted by
// the plugin whose port lands in .opencode/a2a/admin.port. This client works
// with either; resolveControl() probes candidates in order.
//
//   GET    /a2a/sessions                      TaskRecord[]
//   GET    /a2a/sessions/:taskId              TaskRecord
//   POST   /a2a/conversations                 { peer, message, origin? } -> TurnResult
//   POST   /a2a/conversations/:taskId/messages { message } -> TurnResult
//   POST   /a2a/conversations/:taskId/cancel  -> { taskId, state }
//   GET    /a2a/peers                         { peers: { name, url }[] }
//   POST   /a2a/peers                         { name, url } -> { peers }
//   DELETE /a2a/peers/:name                   -> { peers }
//   POST   /a2a/peers/:name/test              -> { peer, name, description }

export const ADMIN_PORT_FILE = path.join(".opencode", "a2a", "admin.port")
export const ADMIN_URL_ENV = "OPENCODE_A2A_ADMIN_URL"

const Timestampish = z.union([z.number(), z.string()])

// Every task this instance knows about, both directions (the A2A-014
// registry row). Optional fields stay optional so older/partial
// implementations still parse.
export const ControlSessionSchema = z.object({
  taskId: z.string(),
  direction: z.enum(["outbound", "inbound"]).optional(),
  peerId: z.string().optional(),
  origin: z.string().optional(),
  state: TaskStateSchema.optional().default("TASK_STATE_UNSPECIFIED"),
  turns: z.number().int().nonnegative().optional(),
  sessionId: z.string().optional(),
  // Status text from the last transition — the turn-cap message lands here.
  message: z.string().optional(),
  // The verdict the task produced, when it produced one.
  artifact: ArtifactSchema.optional(),
  createdAt: Timestampish.optional(),
  updatedAt: Timestampish.optional(),
})
export type ControlSession = z.infer<typeof ControlSessionSchema>

// One message in a task thread. `content` matches the a2a.conversation.turn
// event vocabulary; `text` is accepted for simple implementations.
export const ControlTurnSchema = z.object({
  index: z.number().int().nonnegative().optional(),
  speaker: SpeakerSchema.optional().default("remote"),
  peerId: z.string().optional(),
  content: z.string().optional(),
  text: z.string().optional(),
})
export type ControlTurn = z.infer<typeof ControlTurnSchema>

// Registry TaskTurn (registry.ts): the recorded conversation the detail route
// serves so a thread can render after the fact, not only from live events.
const HistoryTurnSchema = z
  .object({
    speaker: SpeakerSchema,
    turn: z.number().int().nonnegative(),
    peerId: z.string().optional(),
    content: z.string(),
  })
  .transform((turn): ControlTurn => ({
    index: turn.turn,
    speaker: turn.speaker,
    peerId: turn.peerId,
    content: turn.content,
  }))

const SessionsResponseSchema = z.union([
  z.object({ sessions: z.array(ControlSessionSchema) }),
  z.array(ControlSessionSchema).transform((sessions) => ({ sessions })),
])

const SessionDetailSchema = z.union([
  z
    .object({
      session: ControlSessionSchema.and(z.object({ history: z.array(HistoryTurnSchema).optional() })),
      turns: z.array(ControlTurnSchema).optional(),
    })
    .transform((detail) => ({ session: detail.session, turns: detail.turns ?? detail.session.history ?? [] })),
  ControlSessionSchema.and(z.object({ history: z.array(HistoryTurnSchema).optional() })).transform((record) => ({
    session: record,
    turns: record.history ?? [],
  })),
])
export type SessionDetail = z.infer<typeof SessionDetailSchema>

// What POST /a2a/conversations* returns — one turn's outcome, matching
// ConversationResult in conversation.ts.
const TurnResultSchema = z.object({
  peerId: z.string(),
  taskId: z.string().optional(),
  turn: z.number().int().optional(),
  reply: z.string().optional(),
  artifact: z.string().optional(),
  message: z.string().optional(),
  state: TaskStateSchema,
  capped: z.boolean().optional(),
  terminal: z.boolean().optional(),
})
export type TurnResult = z.infer<typeof TurnResultSchema>

const CancelResultSchema = z.object({
  taskId: z.string(),
  state: TaskStateSchema,
})

export const ControlPeerSchema = z.object({
  name: z.string(),
  url: z.string(),
})
export type ControlPeer = z.infer<typeof ControlPeerSchema>

const PeersResponseSchema = z.object({
  peers: z.array(ControlPeerSchema).optional().default([]),
  // Own identity + listener status for the peers dashboard. The admin API
  // serves this from GET /a2a/self instead; peers() merges it here so views
  // read one shape. (The stub still inlines it, which is why the field
  // survives on this schema.)
  self: z
    .object({
      name: z.string().optional(),
      port: z.number().optional(),
      enabled: z.boolean().optional(),
    })
    .optional(),
  // False when allowedPeers can't be edited through the API (env-only enable,
  // read-only config); `hint` then tells the user what to edit by hand.
  writable: z.boolean().optional(),
  hint: z.string().optional(),
})
export type PeersInfo = z.infer<typeof PeersResponseSchema>

// GET /a2a/self (admin.ts): the identity a peer should add, plus reachability.
const SelfResponseSchema = z.object({
  enabled: z.boolean().optional(),
  name: z.string().optional(),
  listenPort: z.number().optional(),
  url: z.string().optional(),
  lanUrls: z.array(z.string()).optional(),
})

const PeerTestSchema = z.object({
  peer: z.string(),
  // The peer's claimed agent-card name — may differ from the local
  // allowedPeers key, which is only a local label (A2A-013).
  name: z.string(),
  description: z.string().optional(),
})
export type PeerTest = z.infer<typeof PeerTestSchema>

export class ControlError extends Error {
  readonly status?: number

  constructor(message: string, status?: number) {
    super(message)
    this.name = "ControlError"
    this.status = status
  }
}

export type ControlFetch = (input: string | URL | Request, init?: RequestInit) => Promise<Response>

export interface A2AControl {
  sessions(): Promise<ControlSession[]>
  session(taskId: string): Promise<SessionDetail>
  start(peer: string, text: string): Promise<TurnResult>
  reply(taskId: string, text: string): Promise<TurnResult>
  cancel(taskId: string): Promise<{ taskId: string; state: ControlSession["state"] }>
  peers(): Promise<PeersInfo>
  addPeer(name: string, url: string): Promise<void>
  removePeer(name: string): Promise<void>
  testPeer(name: string): Promise<PeerTest>
}

export function createControl(base: string, fetcher: ControlFetch = fetch): A2AControl {
  const origin = base.replace(/\/+$/, "")

  async function request<T>(method: string, route: string, body: unknown, schema: z.ZodType<T>): Promise<T> {
    let response: Response
    try {
      response = await fetcher(`${origin}${route}`, {
        method,
        headers: body === undefined ? undefined : { "content-type": "application/json" },
        body: body === undefined ? undefined : JSON.stringify(body),
      })
    } catch (error) {
      throw new ControlError(error instanceof Error ? error.message : String(error))
    }
    if (!response.ok) throw new ControlError(await errorText(response), response.status)
    if (response.status === 204) return schema.parse(undefined)
    const parsed = schema.safeParse(await response.json().catch(() => undefined))
    if (!parsed.success) throw new ControlError(`unexpected response from ${route}`, response.status)
    return parsed.data
  }

  return {
    sessions: async () => (await request("GET", "/a2a/sessions", undefined, SessionsResponseSchema)).sessions,
    session: (taskId) => request("GET", `/a2a/sessions/${encodeURIComponent(taskId)}`, undefined, SessionDetailSchema),
    start: (peer, text) =>
      request("POST", "/a2a/conversations", { peer, message: text, origin: "tui" }, TurnResultSchema),
    reply: (taskId, text) =>
      request("POST", `/a2a/conversations/${encodeURIComponent(taskId)}/messages`, { message: text }, TurnResultSchema),
    cancel: (taskId) =>
      request("POST", `/a2a/conversations/${encodeURIComponent(taskId)}/cancel`, undefined, CancelResultSchema),
    peers: async () => {
      const info = await request("GET", "/a2a/peers", undefined, PeersResponseSchema)
      if (info.self !== undefined) return info
      const own = await request("GET", "/a2a/self", undefined, SelfResponseSchema).catch(() => undefined)
      if (own === undefined) return info
      return { ...info, self: { name: own.name, port: own.listenPort, enabled: own.enabled } }
    },
    addPeer: async (name, url) => {
      await request("POST", "/a2a/peers", { name, url }, z.unknown())
    },
    removePeer: async (name) => {
      await request("DELETE", `/a2a/peers/${encodeURIComponent(name)}`, undefined, z.unknown())
    },
    testPeer: (name) => request("POST", `/a2a/peers/${encodeURIComponent(name)}/test`, undefined, PeerTestSchema),
  }
}

async function errorText(response: Response): Promise<string> {
  const text = await response.text().catch(() => "")
  const parsed = z
    .object({ error: z.union([z.string(), z.object({ message: z.string() })]) })
    .or(z.object({ message: z.string() }))
    .safeParse(safeJson(text))
  if (parsed.success) {
    const value = "error" in parsed.data ? parsed.data.error : parsed.data.message
    return typeof value === "string" ? value : value.message
  }
  return text || `HTTP ${response.status}`
}

function safeJson(text: string): unknown {
  try {
    return JSON.parse(text)
  } catch {
    return undefined
  }
}

export type ControlSource = {
  base: string
  via: "env" | "server" | "port-file"
}

// Candidates in order:
//   1. OPENCODE_A2A_ADMIN_URL — explicit dev/test override (points at the
//      demo control stub today; also covers non-standard layouts).
//   2. The opencode server's own /a2a/* routes — the preferred A2A-014
//      transport, reached through the same base URL the TUI already uses.
//   3. .opencode/a2a/admin.port under the project/worktree dir — the
//      plugin-hosted loopback fallback.
export async function resolveControl(input: {
  env?: Record<string, string | undefined>
  serverUrl?: string
  directories?: readonly string[]
  fetcher?: ControlFetch
  probeMs?: number
}): Promise<ControlSource | undefined> {
  const fetcher = input.fetcher ?? fetch
  const candidates: { base: string; via: ControlSource["via"] }[] = []

  const env = input.env?.[ADMIN_URL_ENV]
  if (env) candidates.push({ base: env, via: "env" })
  if (input.serverUrl) candidates.push({ base: input.serverUrl, via: "server" })
  for (const directory of input.directories ?? []) {
    const file = Bun.file(path.join(directory, ADMIN_PORT_FILE))
    const text = await file.text().catch(() => undefined)
    const port = Number(text?.trim())
    if (Number.isInteger(port) && port > 0 && port <= 65535) {
      candidates.push({ base: `http://127.0.0.1:${port}`, via: "port-file" })
    }
  }

  for (const candidate of candidates) {
    try {
      new URL(candidate.base)
    } catch {
      continue
    }
    const ok = await probe(candidate.base, fetcher, input.probeMs ?? 1500)
    if (ok) return candidate
  }
  return undefined
}

// A base is only usable when the control API actually answers on it — a
// stale admin.port file or an older server build both fail the probe.
async function probe(base: string, fetcher: ControlFetch, ms: number): Promise<boolean> {
  try {
    const response = await fetcher(`${base.replace(/\/+$/, "")}/a2a/sessions`, {
      signal: AbortSignal.timeout(ms),
    })
    return response.ok
  } catch {
    return false
  }
}

